# 第 10 批（F4）：海洋保育法（113/07/31）第 1 條至第 31 條（全部條文）
# ※ 四個選項刻意寫成相近長度。
OC = "ENV-16"
Q = [
# ---------- 第一章 總則 ----------
(OC,"第1條",1,"海保法-立法目的",
 "制定海洋保育法之立法目的為何？",
 ["為保護海洋生態環境，保育海洋生物多樣性，合理利用海洋生物資源，協調並促進海洋保護區之規劃及執行，推動海洋保育教育","為開發海洋生物資源，培育海洋養殖產業，擴大遠洋漁業作業範圍，協調並促進漁業專用區之劃設及經營，推動漁業經濟教育","為防治海洋污染行為，管制陸源污染排放，合理徵收海洋污染防治費，協調並促進海域監測站之設置及管理，推動污染防治教育","為管理海岸土地使用，確保自然海岸零損失，合理配置海岸防護設施，協調並促進海岸保護區之劃設及執行，推動海岸管理教育"],"a",
 "第1條：為保護海洋生態環境，保育海洋生物多樣性，合理利用海洋生物資源，協調並促進海洋保護區之規劃及執行，推動海洋保育教育，特制定本法。第4條並要求主管機關為達成海洋生物多樣性之目標，應採取各種海洋保育措施，以保護海洋生物棲息環境，協調並促進海洋保護區之整合規劃及執行。",
 "What is the stated legislative purpose of the Marine Conservation Act?",
 ["To protect the marine ecological environment, conserve marine biodiversity, make rational use of marine biological resources, coordinate and promote the planning and implementation of marine protected areas, and advance marine conservation education","To develop marine biological resources, foster the marine aquaculture industry, expand distant-water fishing operations, coordinate and promote the designation and operation of fishery zones, and advance fishery economics education","To prevent acts of marine pollution, control discharges from land-based sources, levy marine pollution control fees, coordinate and promote the installation and management of sea monitoring stations, and advance pollution control education","To manage coastal land use, ensure zero loss of natural coastline, allocate coastal defense facilities rationally, coordinate and promote the designation and implementation of coastal protection zones, and advance coastal management education"],
 "Article 1; Article 4."),

(OC,"第2條",1,"海保法-主管機關",
 "本法所稱主管機關為何？地方主管機關之管轄範圍如何決定？",
 ["中央為海洋委員會，直轄市為直轄市政府，縣（市）為縣（市）政府；地方主管機關之管轄範圍，由中央主管機關公告之","中央為環境部，直轄市為直轄市政府，縣（市）為縣（市）政府；地方主管機關之管轄範圍，由行政院逕行劃定並公告之","中央為農業部，直轄市為直轄市政府，縣（市）為縣（市）政府；地方主管機關之管轄範圍，由各該地方政府自行公告之","中央為內政部，直轄市為直轄市政府，縣（市）為縣（市）政府；地方主管機關之管轄範圍，由中央目的事業主管機關公告"],"a",
 "第2條第1項：本法所稱主管機關，在中央為海洋委員會；在直轄市為直轄市政府；在縣（市）為縣（市）政府。第2項：直轄市、縣（市）主管機關之管轄範圍，由中央主管機關公告之。海洋污染防治法第3條就其主管機關亦採相同之中央機關設計。",
 "Who are the competent authorities, and how is local jurisdiction determined?",
 ["Central: the Ocean Affairs Council; municipal: the municipal governments; county: the county or city governments; local jurisdiction is announced by the central competent authority","Central: the Ministry of Environment; municipal: the municipal governments; county: the county or city governments; local jurisdiction is delimited and announced by the Executive Yuan","Central: the Ministry of Agriculture; municipal: the municipal governments; county: the county or city governments; local jurisdiction is announced by each local government itself","Central: the Ministry of the Interior; municipal: the municipal governments; county: the county or city governments; local jurisdiction is announced by the central industry authority"],
 "Article 2."),

(OC,"第3條",2,"海保法-用詞定義",
 "本法所稱海洋生物多樣性、保育及海洋保護區，其定義為何？",
 ["海洋生物多樣性指所有海洋範圍內活的生物體中之變異性，包括物種內、物種之間及生態系統之多樣性；保育指基於海洋生物多樣性及自然生態平衡之原則，對海洋生物所為保護、復育、管理之行為；海洋保護區指依本法或其他法律所劃定進行保護之海域或其毗連陸域","海洋生物多樣性指經中央主管機關公告之保育類海洋物種名錄總數；保育指禁止一切人為利用海洋生物資源之行為，並包括禁止學術研究採樣在內；海洋保護區指僅依本法所劃定之海洋庇護區，並不包括依其他法律規定劃設之各類保護區域及其毗連陸域在內","海洋生物多樣性指海域內漁獲量與魚種數量之統計指標；保育指基於漁業永續經營原則，對經濟性魚種所為之放流、增殖及配額管理行為；海洋保護區指經漁業主管機關劃定之水產動植物繁殖保育區，其餘區域均不屬之","海洋生物多樣性指海洋生態系統之碳匯能力與固碳總量；保育指基於氣候變遷調適原則，對藍碳生態系所為之復育及碳權管理行為；海洋保護區指依海洋基本法所劃定之重要海洋生態區位，並以陸域緩衝帶為其範圍"],"a",
 "第3條第2至4款：海洋生物多樣性指所有海洋範圍內活的生物體中之變異性，包括物種內、物種之間及生態系統之多樣性；保育指基於海洋生物多樣性及自然生態平衡之原則，對於海洋生物所為保護、復育、管理之行為；海洋保護區指一處海域或該海域與其毗連之陸域具有生物多樣性、特殊自然景觀、文化資產或永續利用之生態資源等，依本法或其他法律所劃定進行保護之區域。第6條並列舉海洋保護區之十一種類型。",
 "How are marine biodiversity, conservation and marine protected areas defined?",
 ["Marine biodiversity means variability among living organisms within all marine areas, including diversity within species, between species and of ecosystems; conservation means protecting, restoring and managing marine organisms on principles of biodiversity and natural ecological balance; a marine protected area is a sea area or its adjoining land designated for protection under this or another law","Marine biodiversity means the total number of conserved marine species appearing on the list announced by the central competent authority; conservation means banning all human use of marine biological resources, including sampling carried out for academic research; a marine protected area means only a marine sanctuary designated under this Act, excluding any protected areas designated under other laws","Marine biodiversity means statistical indicators of catch volume and the number of fish species in an area; conservation means release, propagation and quota management of commercial species on principles of sustainable fisheries; a marine protected area means only an aquatic breeding and conservation area designated by fisheries authorities","Marine biodiversity means the carbon sink capacity and total carbon storage of marine ecosystems; conservation means restoration and carbon credit management of blue carbon ecosystems on climate adaptation principles; a marine protected area means an important ecological location designated under the Ocean Basic Act with a landward buffer"],
 "Article 3, subparagraphs 2-4; Article 6."),

(OC,"第3條",3,"海保法-庇護區分區",
 "海洋庇護區之核心區、緩衝區及永續利用區，其定義為何？",
 ["核心區指為長期保護海洋生物、生態環境、生物多樣性並提供學術研究，應嚴格保護且限制人員進入及所有開發利用行為所劃定之區域；緩衝區指鄰接或環繞於核心區，針對人為活動進行管理、限制以保護核心區，可作為研究發展所劃定之區域；永續利用區指於核心區、緩衝區之外圍，在無礙海洋自然生態平衡前提下容許資源利用之區域","核心區指位於海洋庇護區之最外圍、供一般民眾自由進出並從事各類遊憩活動所劃定公告之區域；緩衝區指鄰接或環繞於永續利用區，專供漁業作業、水產養殖及採捕海洋生物使用所劃定之區域；永續利用區指位於海洋庇護區之最中心處，應嚴格保護並限制人員進入及所有開發利用行為所劃定公告之核心保護區域","核心區指為長期保護海洋生物所劃定並全面禁止學術研究之區域；緩衝區指鄰接核心區而容許一切開發利用行為所劃定之區域；永續利用區指於核心區與緩衝區之間，僅供軍事訓練、海域巡防及國防設施使用所劃定之區域，並禁止一般民眾與漁民進入其中","核心區指依其他法律已劃設保護區而納入庇護區管理所劃定之區域；緩衝區指鄰接原住民族傳統海域，專供原住民族傳統採捕使用之區域；永續利用區指於庇護區外圍海域，供中央主管機關辦理海洋保育觀察及監測任務所劃定使用之專屬區域"],"a",
 "第3條第6至8款：核心區指為長期保護海洋生物、生態環境、生物多樣性，並提供學術研究，應嚴格保護，且限制人員進入及所有開發利用行為所劃定之區域；緩衝區指鄰接或環繞於核心區，針對人為活動進行管理、限制以保護核心區，可作為研究發展所劃定之區域；永續利用區指於核心區、緩衝區之外圍，在無礙海洋自然生態平衡之前提下，容許海洋生物、生態環境、生物多樣性及天然資源之利用之區域。第10條至第12條分別定其管制內容。",
 "How are the core, buffer and sustainable use zones of a marine sanctuary defined?",
 ["The core zone is designated for long-term protection of marine life, environment and biodiversity and for academic research, strictly protected with entry and all development restricted; the buffer zone adjoins or surrounds the core zone, managing and restricting human activity to protect it and available for research and development; the sustainable use zone lies outside both and permits resource use where the natural ecological balance is not impaired","The core zone lies on the outermost edge of the sanctuary and is designated for free public entry and recreation; the buffer zone adjoins or surrounds the sustainable use zone and is designated for fishing operations and aquaculture; the sustainable use zone lies at the sanctuary's center and is strictly protected with entry and all development restricted","The core zone is designated for the long-term protection of marine life, the marine environment and biodiversity, with academic research entirely prohibited inside it; the buffer zone adjoins the core zone and permits all forms of development and resource use without restriction; the sustainable use zone lies between the core and buffer zones and serves only military training, maritime patrol and national defense installations, with the general public and fishers barred from entry","The core zone is an area already designated under other laws and brought into sanctuary management; the buffer zone adjoins traditional indigenous waters and is reserved for traditional indigenous harvesting; the sustainable use zone lies in the outer waters and is reserved for the central authority's observation and monitoring tasks"],
 "Article 3, subparagraphs 6-8; Articles 10-12."),

(OC,"第4條",1,"海保法-保育措施",
 "為達成海洋生物多樣性之目標，主管機關應採取何種作為？",
 ["應採取各種海洋保育措施，以保護海洋生物棲息環境，協調並促進海洋保護區之整合規劃及執行","應採取各種漁業管理措施，以提高海洋生物產量，協調並促進漁業專用區之整合規劃及開發","應採取各種污染防治措施，以降低海域污染負荷，協調並促進海域監測站之整合設置及維護","應採取各種土地管制措施，以限制毗連陸域開發，協調並促進海岸防護區之整合劃設及施工"],"a",
 "第4條：為達成海洋生物多樣性之目標，主管機關應採取各種海洋保育措施，以保護海洋生物棲息環境，協調並促進海洋保護區之整合規劃及執行。第7條並要求中央主管機關會同各中央目的事業主管機關訂定整體海洋保護區管理政策方針，報請行政院核定後實施。",
 "What must the competent authorities do to achieve marine biodiversity goals?",
 ["Take various marine conservation measures to protect marine habitats, and coordinate and promote the integrated planning and implementation of marine protected areas","Take various fishery management measures to raise marine biological output, and coordinate and promote the integrated planning and development of dedicated fishery zones","Take various pollution control measures to reduce the pollution load of sea areas, and coordinate and promote the integrated installation and upkeep of monitoring stations","Take various land control measures to limit development of adjoining land, and coordinate and promote the integrated designation and construction of coastal defense zones"],
 "Article 4; Article 7."),

(OC,"第5條",2,"海保法-原住民族",
 "海洋庇護區之劃定、變更、廢止及保育計畫擬訂前，涉及原住民族土地及海域者應如何辦理？",
 ["中央主管機關應會同中央原住民族主管機關，並依原住民族基本法及海洋基本法之規定辦理","中央主管機關得逕行劃定並於公告後通知中央原住民族主管機關，無須事前會同或依其他法律辦理","應由中央原住民族主管機關單獨劃定該區域，中央主管機關僅負責後續之保育計畫執行及管理","應報請行政院核定後由地方主管機關辦理，並依土地徵收條例規定給予原住民族適當之補償"],"a",
 "第5條：海洋庇護區之劃定、變更或廢止及海洋庇護區保育計畫之擬訂前，涉及原住民族土地及海域部分，中央主管機關應會同中央原住民族主管機關，並依原住民族基本法及海洋基本法之規定辦理。第8條第2項並要求審議會中原住民及漁民團體之代表總人數不得少於委員總人數三分之一；第26條第2項並定明海洋保育講習課程應包含原住民族知識及生物多樣性課程。",
 "What applies where designating, altering or abolishing a marine sanctuary involves indigenous land or waters?",
 ["The central competent authority must act jointly with the central indigenous peoples authority and in accordance with the Indigenous Peoples Basic Act and the Ocean Basic Act","The central competent authority may designate directly and merely notify the central indigenous peoples authority afterwards, with no prior joint action or other law applying","The central indigenous peoples authority alone designates that area, with the central competent authority only implementing and managing the conservation plan afterwards","The matter must go to the Executive Yuan for approval and be handled by local authorities, with compensation to indigenous peoples under the Land Expropriation Act"],
 "Article 5; Articles 8 and 26."),

# ---------- 第二章 海洋保護區 ----------
(OC,"第6條",3,"海保法-保護區類型",
 "本法所定海洋保護區之類型，包括下列哪些地區之海域或其毗連陸域？",
 ["野生動物保護區；野生動物重要棲息環境；國家公園及國家自然公園；國家風景特定區海域資源保護區；水產動植物繁殖保育區；水下文化資產保護區；自然保留區；地質公園；重要濕地；海洋庇護區；依其他法律規定劃設之保護區","野生動物保護區；野生動物重要棲息環境；國家公園及國家自然公園；商港區與工業專用港區；漁港區及遊艇港區；水下文化資產保護區；自然保留區；地質公園；重要濕地；海埔地開發區；依其他法律規定劃設之產業園區","野生動物保護區；海岸保護區與海岸防護區；國家公園及國家自然公園；國家風景特定區陸域遊憩區；水產動植物養殖區；軍事管制區；自然保留區；地質公園；水源保護區；海洋庇護區；依其他法律規定劃設之保安林地","野生動物重要棲息環境；離島綜合建設區；國家公園及國家自然公園；國家風景特定區海域資源保護區；水產動植物繁殖保育區；礦業保留區；自然保留區；地質公園；重要濕地；人工魚礁區；依其他法律規定劃設之禁採區"],"a",
 "第6條第1項：本法所定海洋保護區之類型，包括野生動物保護區、野生動物重要棲息環境、國家公園及國家自然公園、國家風景特定區海域資源保護區、水產動植物繁殖保育區、水下文化資產保護區、自然保留區、地質公園、重要濕地、海洋庇護區及依其他法律規定劃設之保護區等地區之海域或該海域與其毗連之陸域。第2項並定明中央主管機關得認定海洋保護區以外其他有效保育措施之區域。",
 "Which areas' waters, or waters plus adjoining land, count as marine protected areas under this Act?",
 ["Wildlife refuges; major wildlife habitats; national parks and national nature parks; marine resource protection areas of national scenic areas; aquatic breeding and conservation areas; underwater cultural heritage zones; nature reserves; geoparks; important wetlands; marine sanctuaries; and protected areas designated under other laws","Wildlife refuges; major wildlife habitats; national parks and national nature parks; commercial and industrial port zones; fishing and yacht harbor zones; underwater cultural heritage zones; nature reserves; geoparks; important wetlands; reclaimed land development zones; and industrial parks designated under other laws","Wildlife refuges; coastal protection and defense zones; national parks and national nature parks; land recreation areas of national scenic areas; aquaculture zones; military control areas; nature reserves; geoparks; water source protection areas; marine sanctuaries; and protection forests designated under other laws","Major wildlife habitats; offshore island development zones; national parks and national nature parks; marine resource protection areas of national scenic areas; aquatic breeding and conservation areas; mining reserve areas; nature reserves; geoparks; important wetlands; artificial reef zones; and no-extraction areas designated under other laws"],
 "Article 6, paragraphs 1 and 2."),

(OC,"第6條",2,"海保法-其他有效保育措施",
 "海洋保護區以外之區域，中央主管機關得為何種認定？其認定標準由誰訂定？",
 ["得認定為其他有效保育措施之區域；其認定標準，由中央主管機關定之","得認定為海洋庇護區之核心區；其認定標準，由行政院會商有關機關定之","得認定為漁業資源保育區；其認定標準，由中央漁業主管機關會商地方定之","得認定為國家級重要濕地；其認定標準，由內政部會商中央主管機關定之"],"a",
 "第6條第2項：中央主管機關得認定海洋保護區以外其他有效保育措施之區域；其認定標準，由中央主管機關定之。第7條並要求依其他法律規定劃設之海洋保護區，其保護區名稱、內容、劃設程序、辦理機關及管理事項從其規定，納入整體海洋保護區管理政策方針之一部。",
 "What may the central authority recognize outside marine protected areas, and who sets the criteria?",
 ["It may recognize areas with other effective conservation measures; the recognition criteria are set by the central competent authority","It may recognize them as core zones of a marine sanctuary; the recognition criteria are set by the Executive Yuan with relevant agencies","It may recognize them as fishery resource conservation areas; the criteria are set by the central fisheries authority with local authorities","It may recognize them as nationally important wetlands; the criteria are set by the Ministry of the Interior with the central authority"],
 "Article 6, paragraph 2; Article 7."),

(OC,"第7條",3,"海保法-政策方針",
 "整體海洋保護區管理政策方針應由誰訂定？其內容應包括哪些事項？",
 ["由中央主管機關會同各中央目的事業主管機關訂定，報請行政院核定後實施；內容應包括政策目標、海洋保護區之分類及分級、海洋保護區之規劃及管理、海洋保護區之監測、海洋保護區之檢討及成效評估","由中央主管機關會同各中央目的事業主管機關訂定，報請立法院審議後實施；內容應包括政策目標、海洋保護區之土地權屬、海洋保護區之徵收補償、海洋保護區之招商、海洋保護區之開發利益回饋比率","由行政院會同中央原住民族主管機關訂定，交由地方主管機關分別實施；內容應包括政策目標、海洋保護區之分類及分級、海洋保護區之巡防勤務、海洋保護區之罰鍰額度、海洋保護區之檢舉獎金基準","由各中央目的事業主管機關分別訂定其主管保護區之方針，報中央主管機關備查；內容應包括政策目標、海洋保護區之漁獲配額、海洋保護區之養殖許可、海洋保護區之遊憩收費、海洋保護區之觀光行銷"],"a",
 "第7條第1項：中央主管機關應會同各中央目的事業主管機關訂定整體海洋保護區管理政策方針，報請行政院核定後實施；其變更時亦同。第2項：內容應包括政策目標、海洋保護區之分類及分級、海洋保護區之規劃及管理、海洋保護區之監測、海洋保護區之檢討及成效評估及其他與海洋保護區管理有關之事項。第3項並要求實施後每五年至少檢討一次。",
 "Who sets the overall marine protected area management policy guidelines, and what must they cover?",
 ["The central authority together with the central industry authorities, effective after Executive Yuan approval; they must cover policy objectives, classification and grading of protected areas, their planning and management, their monitoring, and their review and effectiveness assessment","The central authority together with the central industry authorities, effective after Legislative Yuan review; they must cover policy objectives, land ownership in protected areas, expropriation compensation, investment attraction, and development benefit feedback ratios in those areas","The Executive Yuan together with the central indigenous peoples authority, implemented separately by local authorities; they must cover policy objectives, classification and grading, patrol duties, fine levels, and criteria for informant rewards","Each central industry authority for the areas it administers, filed with the central authority for record; they must cover policy objectives, catch quotas, aquaculture permits, recreation charges, and tourism marketing in protected areas"],
 "Article 7, paragraphs 1-3."),

(OC,"第7條",2,"海保法-方針檢討",
 "整體海洋保護區管理政策方針實施後應多久檢討一次？涉及相關機關執行有疑義時如何處理？",
 ["中央主管機關應每五年至少檢討一次；涉及相關機關執行有疑義時，得由中央主管機關協調，協調不成者報請行政院決定之","中央主管機關應每十年至少檢討一次；涉及相關機關執行有疑義時，得由各中央目的事業主管機關逕行決定，中央主管機關不得介入","中央主管機關應每三年至少檢討一次；涉及相關機關執行有疑義時，應由立法院作成決議後辦理，行政院不得逕行決定其執行方式","中央主管機關得視需要決定是否檢討；涉及相關機關執行有疑義時，應由地方主管機關協調，協調不成者報請中央主管機關核定"],"a",
 "第7條第3項：整體海洋保護區管理政策方針實施後，中央主管機關應每五年至少檢討一次。第5項：整體海洋保護區管理政策方針涉及相關機關執行有疑義時，得由中央主管機關協調；協調不成者，報請行政院決定之。第4項並定明依其他法律規定劃設之海洋保護區從其規定，納入該方針之一部。",
 "How often must the policy guidelines be reviewed, and how are inter-agency doubts resolved?",
 ["The central authority must review them at least once every five years; where agencies have doubts over implementation, the central authority may coordinate, and failing agreement report to the Executive Yuan for decision","The central authority must review them at least once every ten years; where agencies have doubts over implementation, each central industry authority decides directly and the central authority may not intervene","The central authority must review them at least once every three years; where agencies have doubts over implementation, the Legislative Yuan must resolve the matter and the Executive Yuan may not decide","The central authority may decide whether to review them at all; where agencies have doubts, local authorities coordinate and, failing agreement, report to the central authority for approval"],
 "Article 7, paragraphs 3-5."),

(OC,"第8條",3,"海保法-庇護區劃定",
 "中央主管機關於何種情形得劃定海洋庇護區？核心區劃定致特別犧牲損失者如何處理？",
 ["得就海洋生態系統有特別保護必要，且未經其他主管機關劃設為海洋保護區者，劃定為海洋庇護區；海洋庇護區之核心區劃定致該區域之既有使用人遭受特別犧牲之損失者，應予補償","得就任何具觀光遊憩潛力之海域，不論是否已由其他主管機關劃設為海洋保護區，均劃定為海洋庇護區；核心區劃定致既有使用人遭受損失者，應由該使用人自行承擔而不予補償","得就已由其他主管機關劃設為海洋保護區之海域，重複劃定為海洋庇護區以加強保護；核心區劃定致既有使用人遭受特別犧牲之損失者，應由地方主管機關編列預算全額補償","得就經漁業主管機關同意釋出之漁業權海域，劃定為海洋庇護區；核心區劃定致既有使用人遭受特別犧牲之損失者，應由後續進入該區域之開發業者負擔全部補償費用"],"a",
 "第8條第1項：中央主管機關得就海洋生態系統有特別保護必要，且未經其他主管機關劃設為海洋保護區者，劃定為海洋庇護區。第4項：海洋庇護區之核心區劃定，致該區域之既有使用人遭受特別犧牲之損失者，應予補償。第5項並授權中央主管機關訂定劃定基準、變更廢止程序、審議會設置及補償條件基準等辦法。第29條另就既有合法權利設有過渡規定。",
 "When may the central authority designate a marine sanctuary, and what if core zone designation causes special sacrifice?",
 ["It may designate a marine sanctuary where a marine ecosystem specially needs protection and has not been designated a protected area by another authority; where core zone designation causes existing users to suffer a loss amounting to special sacrifice, compensation must be paid","It may designate any waters with tourism potential as a marine sanctuary whether or not another authority has designated them a protected area; where core zone designation causes existing users loss, the users bear it themselves without compensation","It may redesignate waters already designated as marine protected areas by another competent authority as marine sanctuaries to strengthen their protection; where core zone designation causes special sacrifice, the local competent authority must budget for full compensation","It may designate as a marine sanctuary any waters whose fishing rights the fisheries authority agrees to release; where core zone designation causes special sacrifice, developers later entering the area bear the entire compensation cost"],
 "Article 8, paragraphs 1, 4 and 5; Article 29."),

(OC,"第8條",3,"海保法-審議會",
 "中央主管機關為辦理海洋庇護區劃定業務所設審議會，其組成及決議門檻為何？",
 ["由專家學者、原住民、漁民團體、保育團體等民間團體及有關機關代表組成，不具官方身分之代表人數不得少於委員總人數二分之一，原住民及漁民團體之代表總人數不得少於三分之一；決議以委員過半數之出席，出席委員超過三分之二同意行之","由專家學者、原住民、漁民團體、保育團體等民間團體及有關機關代表組成，不具官方身分之代表人數不得少於委員總人數三分之一，原住民及漁民團體之代表總人數不得少於四分之一；決議以委員三分之一之出席，出席委員過半數同意行之","由各中央目的事業主管機關代表組成，並得邀請專家學者列席陳述意見但無表決權，原住民及漁民團體之代表僅得旁聽；決議以委員過半數之出席，出席委員過半數同意行之，可否同數時取決於主席","由中央主管機關首長指定之機關代表及其遴聘之專家學者組成，不具官方身分之代表人數不得多於委員總人數二分之一，原住民及漁民團體之代表總人數不得多於三分之一；決議以全體委員三分之二以上同意行之"],"a",
 "第8條第2項：中央主管機關為辦理海洋庇護區劃定業務，應設審議會，由專家學者、原住民、漁民團體、保育團體等民間團體及有關機關代表組成，其中不具官方身分之代表人數不得少於委員總人數二分之一，原住民及漁民團體之代表總人數，不得少於委員總人數三分之一。第3項：審議會之決議，以委員過半數之出席，出席委員超過三分之二同意行之。第14條第2項並定明中央主管機關辦理公告業務時準用第8條第2項規定。",
 "How is the review committee for marine sanctuary designation composed, and what is its voting threshold?",
 ["It comprises scholars, indigenous persons, fishers' groups, conservation groups and other civil groups plus agency representatives, with non-official representatives not fewer than one half of all members and indigenous and fishers' group representatives not fewer than one third; resolutions require a majority present and more than two thirds of those present in favor","It comprises scholars, indigenous persons, fishers' groups, conservation groups and other civil groups plus agency representatives, with non-official representatives not fewer than one third and indigenous and fishers' group representatives not fewer than one quarter; resolutions require one third of all members present and a simple majority of those present in favor","It comprises representatives of the central industry authorities, with scholars invited to attend and state opinions but without voting rights and indigenous and fishers' groups only observing; resolutions require a majority present and a majority of those present in favor, the chair casting the deciding vote","It comprises agency representatives designated by the head of the central authority plus scholars it appoints, with non-official representatives not more than one half of all members and indigenous and fishers' group representatives not more than one third; resolutions require the consent of two thirds of all members"],
 "Article 8, paragraphs 2 and 3; Article 14, paragraph 2."),

(OC,"第9條",2,"海保法-保育計畫",
 "中央主管機關劃定海洋庇護區後，應如何擬訂並公開其保育計畫？",
 ["應會商有關機關擬訂海洋庇護區保育計畫，並公開展覽三十日及舉行公聽會，其變更或廢止時亦同；公告實施後應將計畫登載於政府公報、新聞紙、網際網路或以其他適當方法廣泛周知","應會商有關機關擬訂海洋庇護區保育計畫，並公開展覽十五日及舉行說明會，其變更或廢止時免再辦理；公告實施後僅須將計畫函送當地地方主管機關及鄉鎮市區公所備查即可","應由地方主管機關擬訂海洋庇護區保育計畫報中央核定，並公開展覽六十日及舉行聽證，其變更或廢止時亦同；公告實施後應將計畫送請立法院審查並登載於政府公報周知","應委由學術研究機構擬訂海洋庇護區保育計畫，免經公開展覽及公聽程序即得公告實施；公告實施後應將計畫登載於政府公報、新聞紙或以其他適當方法廣泛周知並副知有關機關"],"a",
 "第9條第1項：中央主管機關劃定海洋庇護區後，應會商有關機關，擬訂海洋庇護區保育計畫，並公開展覽三十日及舉行公聽會；其變更或廢止時亦同。第2項：公開展覽與公聽會之日期及地點，應登載於政府公報、新聞紙、網際網路或以其他適當方法廣泛周知；人民、法人或團體得於公開展覽期間內以書面載明姓名或名稱及地址向中央主管機關提出意見。第3項：公告實施後應將計畫登載周知。",
 "After designating a marine sanctuary, how must the central authority draft and publicize the conservation plan?",
 ["It must draft the plan in consultation with relevant agencies, display it publicly for thirty days and hold a public hearing, doing likewise for changes or repeal; after announcement the plan must be published in the gazette, newspapers, online or by other suitable means","It must draft the plan in consultation with relevant agencies, display it for fifteen days and hold a briefing, with no further procedure for changes or repeal; after announcement it need only be filed with the local governments and township offices for record purposes","Local authorities must draft the plan for central approval, display it for sixty days and hold a hearing, doing likewise for changes or repeal; after announcement the plan must be sent to the Legislative Yuan for review and published in the gazette","Academic institutions may be commissioned to draft the plan, which may be announced without any display or hearing procedure; after announcement it must be published in the gazette, newspapers or by other suitable means and copied to relevant agencies"],
 "Article 9, paragraphs 1-3."),

# ---------- 核心區、緩衝區、永續利用區 ----------
(OC,"第10條",3,"海保法-核心區禁入",
 "任何人及海陸域交通工具進入海洋庇護區核心區之禁止規定，有哪些例外？",
 ["國家安全或軍事目的；海域巡防、犯罪查緝、漁業巡護、污染防治、海難救助、航路標識設置管理、海洋保育、水下文化資產之保存或管理等公務目的；船舶連續不停迅速通過且未從事航行以外之活動；經中央主管機關同意之科學研究、監測或調查等活動","國家安全或軍事目的；海域巡防、犯罪查緝、漁業巡護、污染防治、海難救助等公務目的；船舶於核心區內下錨停泊補給並從事船員休憩活動；經地方主管機關書面同意之商業性漁撈作業、水產養殖經營或潛水遊憩等各類營利性活動行為","國家安全或軍事目的；海洋觀光、遊艇停泊、水上活動經營、海釣船作業等遊憩目的；船舶連續不停迅速通過且未從事航行以外之活動；經目的事業主管機關備查之探礦、採礦或海底電纜鋪設等開發活動","公務機關辦理任何業務之目的；海域巡防、犯罪查緝、漁業巡護、污染防治等公務目的；船舶於核心區內從事拖網或流刺網作業；經中央主管機關公告之一定種類、數量、方式或期間內之採捕海洋生物行為"],"a",
 "第10條第1項：任何人及海陸域交通工具禁止進入海洋庇護區之核心區，但有下列情形之一者不在此限：一、國家安全或軍事目的。二、海域巡防、犯罪查緝、漁業巡護、污染防治、海難救助、航路標識設置管理、海洋保育、水下文化資產之保存或管理等公務目的。三、船舶連續不停迅速通過，且未從事航行以外之活動。四、經中央主管機關同意之科學研究、監測或調查等活動。第2項並授權中央主管機關會商有關機關訂定第4款申請同意之辦法。",
 "What exceptions apply to the ban on entering the core zone of a marine sanctuary?",
 ["National security or military purposes; official purposes such as maritime patrol, crime investigation, fishery patrol, pollution control, sea rescue, navigation aid installation and management, marine conservation, and preservation or management of underwater cultural heritage; continuous and expeditious passage of a ship engaged in no activity other than navigation; and scientific research, monitoring or surveys consented to by the central authority","National security or military purposes; official purposes such as maritime patrol, crime investigation, fishery patrol, pollution control, sea rescue and the routine collection of oceanographic data and weather observations; ships anchoring inside the core zone to take on fuel and supplies and to let the crew rest and recreate on board; and commercial fishing, aquaculture or dive tourism activities consented to in writing by the local competent authority concerned","National security or military purposes; recreational purposes such as marine tourism, yacht mooring, water activity operations and sport fishing boat operations; continuous and expeditious passage of a ship engaged in no activity other than navigation; and mineral exploration, mining or submarine cable laying filed with the relevant industry authority","The purposes of any business handled by a public agency; official purposes such as maritime patrol, crime investigation, fishery patrol and pollution control; ships carrying out trawling or drift gillnet operations inside the core zone; and taking marine organisms within the types, quantities, methods or periods announced by the central authority"],
 "Article 10, paragraphs 1 and 2."),

(OC,"第10條",2,"海保法-核心區罰則",
 "違反規定進入海洋庇護區核心區者應如何處罰？誤入者之處理為何？",
 ["處行為人、海陸域交通工具駕駛人或船長新臺幣五萬元以上五十萬元以下罰鍰；誤入核心區經勸導駛離者不罰，但其為最近二年內經勸導又再違反者，不在此限","處行為人、海陸域交通工具駕駛人或船長新臺幣三萬元以上三十萬元以下罰鍰；誤入核心區經勸導駛離者不罰，但其為最近一年內經勸導又再違反者，不在此限","處行為人、海陸域交通工具駕駛人或船長新臺幣一萬元以上十五萬元以下罰鍰；誤入核心區者一律不罰，縱使最近二年內曾經勸導又再違反者，仍不予處罰","處行為人、海陸域交通工具駕駛人或船長新臺幣二萬元以上十萬元以下罰鍰；誤入核心區經勸導駛離者仍應處以最低額罰鍰，並令其接受海洋保育講習課程"],"a",
 "第21條第1項：違反第10條第1項規定，進入海洋庇護區之核心區者，處行為人、海陸域交通工具駕駛人或船長新臺幣五萬元以上五十萬元以下罰鍰。第2項：誤入海洋庇護區之核心區，經勸導駛離者，不罰；但其為最近二年內經勸導又再違反者，不在此限。第26條第1項並定明違反第10條第1項者，主管機關應令其接受二小時以上十二小時以下之海洋保育講習課程。",
 "How is unlawful entry into a sanctuary core zone penalized, and what applies to accidental entry?",
 ["The actor, the vehicle or vessel operator or the master is fined NT$50,000 to NT$500,000; accidental entry is not punished where the person leaves after advice, unless they were advised and offended again within the past two years","The actor, the vehicle or vessel operator or the master is fined NT$30,000 to NT$300,000; accidental entry is not punished where the person leaves after advice, unless they were advised and offended again within the past one year","The actor, the vehicle or vessel operator or the master is fined NT$10,000 to NT$150,000; accidental entry is never punished, even where the person was advised and offended again within the past two years","The actor, the vehicle or vessel operator or the master is fined NT$20,000 to NT$100,000; accidental entry still attracts the minimum fine even after leaving on advice, plus an order to attend conservation classes"],
 "Article 21; Article 26, paragraph 1."),

(OC,"第11條",3,"海保法-緩衝區管制",
 "海洋庇護區之緩衝區內，非經中央主管機關許可禁止從事哪些行為？何種情形免申請許可？",
 ["禁止水產養殖、採捕海洋生物、開挖濬深航道或施作海洋工程、鋪設電纜管道設施或結構、從事探礦或採礦；其中水產養殖及採捕海洋生物符合中央主管機關公告之一定種類、數量、方式、範圍或期間等條件者，免申請許可","禁止水產養殖、採捕海洋生物、船舶通過、潛水活動、海洋科學研究；其中船舶通過及潛水活動符合中央主管機關公告之一定種類、數量、方式、範圍或期間等條件者，得改向地方主管機關申請核准後為之","禁止開挖濬深航道或施作海洋工程、鋪設電纜管道設施或結構、從事探礦或採礦；其中開挖濬深航道及施作海洋工程符合中央主管機關公告之一定規模、方式或期間等條件者，免申請許可而僅須報請備查","禁止水產養殖、採捕海洋生物、開挖濬深航道或施作海洋工程、鋪設電纜管道設施或結構、從事探礦或採礦；上述行為一律不得申請許可，僅原住民基於傳統文化祭儀生活所需者不受限制"],"a",
 "第11條第1項：海洋庇護區之緩衝區內，非經中央主管機關許可，禁止從事水產養殖、採捕海洋生物、開挖或濬深航道或施作海洋工程、鋪設電纜管道設施或結構、從事探礦或採礦等行為；但符合第10條第1項但書第1款或第2款情形者，不在此限。第2項：從事水產養殖或採捕海洋生物，符合中央主管機關公告之一定種類、數量、方式、範圍或期間等條件者，免申請許可。第13條並授權中央主管機關訂定申請許可辦法。",
 "What is prohibited without permit in a sanctuary buffer zone, and when is no permit needed?",
 ["Aquaculture, taking marine organisms, excavating or deepening channels or building marine works, laying cables, pipelines, facilities or structures, and prospecting or mining are prohibited; aquaculture and taking marine organisms need no permit where they meet the types, quantities, methods, scope or periods announced by the central authority","Aquaculture, taking marine organisms, ship passage, diving activities and marine scientific research are prohibited; ship passage and diving may instead be approved by the local competent authority where they meet the types, quantities, methods, scope or periods announced by the central authority","Excavating or deepening channels or building marine works, laying cables, pipelines, facilities or structures, and prospecting or mining are prohibited; channel excavation and marine works need no permit but only filing where they meet the scale, methods or periods announced by the central authority","Aquaculture, taking marine organisms, excavating or deepening channels or building marine works, laying cables, pipelines, facilities or structures, and prospecting or mining are prohibited; no permit may ever be sought or granted for any of these, and only indigenous traditional cultural, ritual and livelihood needs are exempt from the prohibition"],
 "Article 11; Articles 10 and 13."),

(OC,"第11條",2,"海保法-緩衝區罰則",
 "於海洋庇護區之緩衝區內未經許可從事禁止行為者，應如何處罰？有無除外規定？",
 ["處新臺幣三萬元以上三十萬元以下罰鍰；但原住民基於傳統文化、祭儀、生活所需之利用的行為，不在此限","處新臺幣五萬元以上五十萬元以下罰鍰；但原住民基於傳統文化、祭儀、生活所需之利用的行為，不在此限","處新臺幣一萬元以上十五萬元以下罰鍰；原住民基於傳統文化、祭儀或生活所需之行為，仍應依規定處罰","處新臺幣二萬元以上十萬元以下罰鍰；但經地方主管機關事先同意之營利性採捕行為，得減半處以罰鍰"],"a",
 "第22條：違反第11條第1項規定，於海洋庇護區之緩衝區內，未經許可從事該項所定禁止行為者，處新臺幣三萬元以上三十萬元以下罰鍰；但原住民基於傳統文化、祭儀、生活所需之利用的行為，不在此限。第26條第1項並定明違反第11條第1項者，主管機關應令其接受二小時以上十二小時以下之海洋保育講習課程。",
 "How is unpermitted prohibited activity in a buffer zone penalized, and is there any exemption?",
 ["A fine of NT$30,000 to NT$300,000; but indigenous use for traditional cultural, ritual or livelihood needs is exempt from the prohibition","A fine of NT$50,000 to NT$500,000; but indigenous use for traditional cultural, ritual or livelihood needs is exempt from the prohibition","A fine of NT$10,000 to NT$150,000; indigenous acts for traditional cultural, ritual or livelihood needs are still penalized under the rules","A fine of NT$20,000 to NT$100,000; but commercial harvesting consented to in advance by the local authority attracts only half the fine"],
 "Article 22; Article 26, paragraph 1."),

(OC,"第12條",2,"海保法-永續利用區",
 "海洋庇護區之永續利用區內，非經中央主管機關許可禁止從事哪些行為？",
 ["開挖或濬深航道或施作海洋工程；鋪設電纜、管道、設施或結構；從事探礦或採礦","水產養殖；採捕海洋生物；開挖或濬深航道或施作海洋工程；鋪設電纜或管道","任何人員及海陸域交通工具之進入；船舶航行或停泊；水產養殖及採捕海洋生物","海洋科學研究；監測或調查活動；海洋生物復育措施之投放；人工魚礁之設置"],"a",
 "第12條：海洋庇護區之永續利用區內，非經中央主管機關許可，禁止從事開挖、濬深航道或施作海洋工程、鋪設電纜管道設施或結構、從事探礦或採礦等行為；但符合第10條第1項但書第1款或第2款情形者，不在此限。相較之下，第11條就緩衝區另增列水產養殖及採捕海洋生物二項禁止行為。第23條第1款對違反第12條者，處新臺幣一萬元以上十五萬元以下罰鍰。",
 "What is prohibited without permit in the sustainable use zone of a marine sanctuary?",
 ["Excavating or deepening channels or building marine works; laying cables, pipelines, facilities or structures; and prospecting or mining","Aquaculture; taking marine organisms; excavating or deepening channels or building marine works; and laying cables or pipelines","Entry by any person or land or sea vehicle; navigation or anchoring of ships; and aquaculture and the taking of marine organisms","Marine scientific research; monitoring or survey activities; placement of marine restoration installations; and setting artificial reefs"],
 "Article 12; Articles 11 and 23."),

(OC,"第13條",1,"海保法-許可辦法",
 "緩衝區及永續利用區申請許可之條件、作業程序及廢止許可等事項，應由誰訂定？",
 ["由中央主管機關定之","由行政院會商中央主管機關定之","由各直轄市、縣（市）主管機關定之","由中央漁業主管機關會同中央主管機關定之"],"a",
 "第13條：第11條及第12條申請許可之條件、作業程序、廢止許可及其他相關事項之辦法，由中央主管機關定之。第11條就緩衝區禁止水產養殖、採捕海洋生物、開挖濬深航道或施作海洋工程、鋪設電纜管道及探礦採礦；第12條就永續利用區禁止後三類行為。",
 "Who prescribes the conditions, procedures and revocation rules for permits in buffer and sustainable use zones?",
 ["The central competent authority","The Executive Yuan with the central authority","Each municipal and county competent authority","The central fisheries authority with the central authority"],
 "Article 13; Articles 11 and 12."),

# ---------- 第三章 海洋生物保育 ----------
(OC,"第14條",3,"海保法-公告事項",
 "為保育海洋生物，中央主管機關應會商其他目的事業主管機關公告哪些事項？",
 ["海洋遊憩或休閒活動之限制、禁止或其他應遵行事項；船舶海上航行、活動或作業之限制、禁止或其他應遵行事項；於海洋使用採捕器具之限制、禁止或其他應遵行事項；其他與保育海洋生物有關之人為活動之限制、禁止或應遵行事項","海洋遊憩或休閒活動之收費標準與業者資格條件；船舶海上航行之航路指定與領港作業規定；於海洋使用採捕器具之進口關稅與貨物稅率；其他與海洋產業發展有關之投資獎勵、租稅減免或補助款核發等應遵行事項","海洋保護區之分類分級與劃設程序；海洋庇護區審議會之組成與決議門檻；海洋保育觀察員之資格取得與訓練管理；其他與海洋保護區管理有關之監測、檢討及成效評估等應遵行事項","海洋污染防治費之徵收費率與繳納期限；船舶責任保險之投保額度與擔保方式；海洋棄置物質之甲乙丙分類基準；其他與海洋污染防治有關之許可、申報或紀錄保存等應遵行事項"],"a",
 "第14條第1項：為保育海洋生物，中央主管機關應會商其他目的事業主管機關，公告海洋遊憩或休閒活動之限制、禁止或其他應遵行事項，船舶海上航行、活動或作業之限制、禁止或其他應遵行事項，於海洋使用採捕器具之限制、禁止或其他應遵行事項，及其他與保育海洋生物有關之人為活動之限制、禁止或其他應遵行事項。第23條第2款對違反該公告事項者，處新臺幣一萬元以上十五萬元以下罰鍰。",
 "To conserve marine life, what matters must the central authority announce after consulting other industry authorities?",
 ["Restrictions, prohibitions or other requirements on marine recreation or leisure activities; on ship navigation, activities or operations at sea; on the use of harvesting gear in the sea; and on other human activities relating to the conservation of marine organisms","Fee standards and operator qualifications for marine recreation or leisure activities; route designation and pilotage rules for ship navigation; import duties and commodity tax rates on harvesting gear; and investment incentives, tax relief or subsidies for marine industry development","The classification, grading and designation procedure for marine protected areas; the composition and voting threshold of the sanctuary review committee; the qualification and training of marine conservation observers; and monitoring, review and effectiveness assessment requirements","The rates and payment deadlines of the marine pollution control fee; insurance limits and forms of security for ships; the Class A, B and C criteria for substances dumped at sea; and permit, reporting or record retention requirements for pollution control"],
 "Article 14, paragraph 1; Article 23, subparagraph 2."),

(OC,"第14條",2,"海保法-準用審議",
 "中央主管機關辦理第十四條第一項公告業務時，應準用哪一條規定？其意義為何？",
 ["準用第八條第二項規定，即應設審議會，由專家學者、原住民、漁民團體、保育團體等民間團體及有關機關代表組成，不具官方身分之代表不得少於二分之一，原住民及漁民團體代表不得少於三分之一","準用第八條第三項規定，即決議應以委員過半數之出席、出席委員超過三分之二同意行之，但不必另行組成審議會，得由中央主管機關之內部單位以會簽方式作成決定後公告實施","準用第九條第一項規定，即應會商有關機關擬訂公告草案，並公開展覽三十日及舉行公聽會後始得公告，無須組成任何審議會或遴聘民間團體代表參與審議程序","準用第七條第一項規定，即應會同各中央目的事業主管機關擬訂後報請行政院核定，並於核定後始得公告，其審議程序由行政院逕行指定機關及委員名單辦理"],"a",
 "第14條第2項：中央主管機關辦理前項業務，準用第8條第2項規定。第8條第2項規定中央主管機關應設審議會，由專家學者、原住民、漁民團體、保育團體等民間團體及有關機關代表組成，其中不具官方身分之代表人數不得少於委員總人數二分之一，原住民及漁民團體之代表總人數不得少於委員總人數三分之一。",
 "Which provision applies mutatis mutandis when the central authority makes Article 14(1) announcements, and what does it mean?",
 ["Article 8, paragraph 2 applies, so a review committee must be set up comprising scholars, indigenous persons, fishers' groups, conservation groups and agency representatives, with non-official representatives not fewer than one half and indigenous and fishers' group representatives not fewer than one third","Article 8, paragraph 3 applies, so resolutions require a majority present and more than two thirds of those present in favor, though no committee need be formed and the central authority's internal units may decide by circulation and then announce","Article 9, paragraph 1 applies, so the draft announcement must be prepared in consultation with the relevant agencies, displayed publicly for thirty days and put to a public hearing before announcement, with no review committee formed and no civil group or indigenous peoples representatives appointed","Article 7, paragraph 1 applies, so the matter must be drafted jointly with the central industry authorities and submitted for Executive Yuan approval before announcement, with the Executive Yuan designating the reviewing agency and members"],
 "Article 14, paragraph 2; Article 8, paragraph 2."),

(OC,"第15條",3,"海保法-調查進入",
 "為執行海洋生物資源調查或海洋庇護區保育計畫，主管機關得為何種行為？相對人有何義務？",
 ["主管機關或受託機關（構）、法人、團體得派員出示證明文件，進入公、私有土地、處所或海域進行調查及實施保育措施，涉及軍事機密者應會同該管軍事機關為之；公、私有土地、處所或海域之所有人、使用人或管理人不得規避、妨礙或拒絕","主管機關得派員逕行進入公、私有土地、處所或海域進行調查，無須出示任何證明文件，涉及軍事機密者亦得單獨為之；公、私有土地、處所或海域之所有人、使用人或管理人得於認有妨礙其權益之情形時拒絕調查人員進入","主管機關應先取得法院核發之許可裁定，始得進入公、私有土地、處所或海域進行調查，涉及軍事機密者應報請行政院核准；公、私有土地、處所或海域之所有人、使用人或管理人得聲明異議並停止調查","主管機關僅得委託學術研究機構進入公、私有土地、處所或海域進行調查，不得自行派員辦理，涉及軍事機密者一律不得進入；公、私有土地、處所或海域之所有人、使用人或管理人有協助提供交通工具之義務"],"a",
 "第15條第1項：為執行海洋生物資源調查或海洋庇護區保育計畫，主管機關或受託機關（構）、法人、團體得派員出示證明文件，進入公、私有土地、處所或海域進行調查及實施保育措施；其涉及軍事機密者，應會同該管軍事機關為之。第2項：公、私有土地、處所或海域之所有人、使用人或管理人不得規避、妨礙或拒絕。第24條第1款對無正當理由規避、妨礙或拒絕者，處新臺幣二萬元以上十萬元以下罰鍰。",
 "What may the authority do to carry out resource surveys or sanctuary conservation plans, and what must the other party do?",
 ["The authority or a commissioned agency, juridical person or group may send personnel showing credentials to enter public or private land, premises or waters to survey and carry out conservation measures, acting jointly with the military authority where military secrets are involved; owners, users or managers may not evade, obstruct or refuse","The authority or a commissioned body may send personnel to enter public or private land, premises or waters to survey and carry out measures without showing any credentials, and may act alone even where military secrets are involved; owners, users or managers may refuse entry wherever they consider that their own rights would be prejudiced","The authority must first obtain a court order before entering public or private land, premises or waters to survey, and must obtain Executive Yuan approval where military secrets are involved; owners, users or managers may object and thereby halt the survey","The authority may only commission academic institutions to enter public or private land, premises or waters to survey and may not send its own staff, and may never enter where military secrets are involved; owners, users or managers must help provide transport"],
 "Article 15, paragraphs 1 and 2; Article 24, subparagraph 1."),

(OC,"第15條",3,"海保法-調查程序",
 "進行海洋生物資源調查或實施保育措施時，應踐行哪些程序？造成特別犧牲損失者如何處理？",
 ["遇設有圍障之土地或實施保育措施時，主管機關應事先通知所有人、使用人或管理人，通知未能送達時得以公告方式為之；應恪遵正當法律程序，以符合比例原則之方式為之，對受檢之工商軍事秘密應予保密；致所有人、使用人遭受特別犧牲之損失者，應予補償","遇設有圍障之土地或實施保育措施時，主管機關得逕行破除圍障進入而免事先通知，事後亦無須公告；調查人員得依業務需要公開受檢之工商軍事秘密；致所有人、使用人遭受特別犧牲之損失者，由其自行承擔而不予補償","遇設有圍障之土地或實施保育措施時，主管機關應於三十日前以雙掛號通知所有人，通知未能送達時應停止調查；應恪遵正當法律程序，對受檢之工商軍事秘密應予保密；致所有人或使用人遭受任何損失者，一律按當期公告地價加倍計算補償金額","遇設有圍障之土地或實施保育措施時，主管機關應取得所有人書面同意始得進入，未獲同意者不得調查；調查人員得就受檢之工商秘密提供學術研究使用；致所有人、使用人遭受特別犧牲之損失者，得申請減免其應納稅捐"],"a",
 "第15條第3項：進行調查或實施各項保育措施，遇設有圍障之土地或實施各項保育措施時，主管機關應事先通知所有人、使用人或管理人；通知未能送達時，得以公告方式為之。第4項：調查機關（構）、法人、團體或保育人員應恪遵正當法律程序，以符合比例原則之方式為之，對於受檢之工商軍事秘密應予保密。第5項：致所有人、使用人遭受特別犧牲之損失者，應予補償。第6項並授權中央主管機關訂定方式、通知及補償條件基準之辦法。",
 "What procedures apply to surveys and conservation measures, and what if special sacrifice results?",
 ["For enclosed land or when carrying out measures, the authority must notify the owner, user or manager in advance, using public notice where service fails; it must observe due process and proportionality and keep business and military secrets confidential; where owners or users suffer a loss amounting to special sacrifice, compensation must be paid","For enclosed land or when carrying out measures, the authority may break through the enclosure without prior notice and need not give public notice afterwards; surveyors may disclose business and military secrets as their work requires; owners or users suffering a loss amounting to special sacrifice must bear it themselves without any compensation","For enclosed land or when carrying out measures, the authority must give thirty days' notice by registered mail and must halt the survey where service fails; it must observe due process and keep business and military secrets confidential; any loss to owners is compensated at double the assessed land value","For enclosed land or when carrying out measures, the authority must obtain the owner's written consent before entry and may not survey without it; surveyors may release business secrets for academic research; owners or users suffering special sacrifice may apply for a reduction of their taxes"],
 "Article 15, paragraphs 3-6."),

(OC,"第16條",3,"海保法-觀察員",
 "主管機關指派之海洋保育觀察員，其任務及相對人義務為何？",
 ["得在船舶、海洋設施、海域工程或其周圍從事觀察、監測及蒐集資料等任務，必要時得請求海岸巡防機關或警察機關協助；船舶、海洋設施或海域工程之所有人、使用人或管理人不得規避、妨礙或拒絕","得在船舶、海洋設施、海域工程或其周圍從事取締、蒐證及裁處罰鍰等任務，必要時得逕行扣押相關設備；船舶、海洋設施或海域工程之所有人、使用人或管理人得於作業期間拒絕其登臨","僅得於船舶停靠港口期間進行文件審查及紀錄查核，不得隨船出海執行任務；船舶、海洋設施或海域工程之所有人、使用人或管理人僅須配合提供文件，得拒絕其進入作業區域","得在船舶、海洋設施、海域工程或其周圍從事觀察、監測及蒐集資料等任務，但須事先取得所有人書面同意；船舶、海洋設施或海域工程之所有人、使用人或管理人得隨時要求其離開現場"],"a",
 "第16條第1項：主管機關得指派海洋保育觀察員，在船舶、海洋設施、海域工程或其周圍，從事觀察、監測及蒐集資料等任務；必要時，得請求海岸巡防機關或警察機關協助。第2項：船舶、海洋設施或海域工程之所有人、使用人或管理人，不得規避、妨礙或拒絕。第24條第2款對無正當理由規避、妨礙或拒絕者，處新臺幣二萬元以上十萬元以下罰鍰。",
 "What are the tasks of marine conservation observers, and what duty falls on the other party?",
 ["They may observe, monitor and collect data on or around ships, marine facilities and marine works, and may request assistance from the coast guard or police where necessary; owners, users or managers of ships, facilities or works may not evade, obstruct or refuse","They may carry out interception, evidence-gathering and the imposition of fines on or around ships, marine facilities and marine works, and may seize equipment directly where necessary; owners, users or managers may refuse to let them board during operations","They may only review documents and audit records while a ship is berthed in port and may not go to sea aboard it; owners, users or managers need only supply documents and may refuse them entry to the operating area","They may observe, monitor and collect data on or around ships, marine facilities and marine works, but only with the owner's prior written consent; owners, users or managers may require them to leave the site at any time"],
 "Article 16, paragraphs 1 and 2; Article 24, subparagraph 2."),

(OC,"第16條",2,"海保法-觀察員管理",
 "海洋保育觀察員執行任務時之交通及其資格管理事項，本法如何規定？",
 ["執行觀察、監測及蒐集資料等任務時，得由船舶、海洋設施或海域工程之所有人、使用人或管理人提供往返交通工具；其資格取得、訓練、管理、廢止資格及其他相關事項之辦法，由中央主管機關定之","執行任務時之往返交通工具應由主管機關自行提供，不得要求業者提供；其資格取得、訓練、管理及廢止資格等事項之辦法，由中央主管機關會商交通部及航政機關共同訂定後公告實施","執行任務時之往返交通費用應由觀察員自行負擔並檢據報支；其資格取得、訓練、管理及廢止資格等事項，由各直轄市、縣（市）主管機關分別訂定自治規則並報中央備查","執行任務時得逕行徵用民間船舶作為往返交通工具而不予補償；其資格取得、訓練、管理及廢止資格等事項之辦法，由海岸巡防機關會同警察機關擬訂後報請行政院核定"],"a",
 "第16條第3項：海洋保育觀察員執行觀察、監測及蒐集資料等任務時，得由船舶、海洋設施或海域工程之所有人、使用人或管理人提供往返交通工具。第4項：海洋保育觀察員之資格取得、訓練、管理、廢止資格及其他相關事項之辦法，由中央主管機關定之。第2項並定明所有人、使用人或管理人不得規避、妨礙或拒絕。",
 "How does the Act deal with observers' transport and their qualification management?",
 ["When observing, monitoring and collecting data they may be provided transport to and from the site by the owner, user or manager of the ship, facility or works; the rules on qualification, training, management and revocation are set by the central authority","Transport to and from the site must be provided by the authority itself and may not be demanded of operators; the rules on qualification, training, management and revocation are set by the central authority with the transport ministry and maritime agencies","Travel costs to and from the site must be borne by the observers and claimed against receipts; qualification, training, management and revocation are governed by self-government rules made by each local authority and filed centrally","Private vessels may be requisitioned as transport without any compensation; the rules on qualification, training, management and revocation are drafted by the coast guard with the police for Executive Yuan approval"],
 "Article 16, paragraphs 2-4."),

(OC,"第17條",2,"海保法-協助取締獎勵",
 "執法人員、民眾、法人或團體主動參與或協助取締、舉發違法事件者，主管機關應如何處理？",
 ["主管機關得予獎勵，並對其身分應予保密；獎勵之對象、基準、範圍及其他相關事項之辦法，由中央主管機關定之","主管機關應發給定額獎金，但無保密義務；獎勵之對象、基準及範圍等事項之辦法，由地方主管機關分別訂定","主管機關得予獎勵，但應將其身分資料送交司法機關備查；獎勵之對象、基準及範圍，由行政院逐案核定後發給","主管機關僅對執法人員予以獎勵，民眾及團體不予獎勵；執法人員之獎勵基準依公務人員考績法之規定辦理"],"a",
 "第17條第1項：執法人員、民眾、法人或團體主動參與或協助主管機關取締、舉發本法違法事件者，主管機關得予獎勵。第2項：主管機關對於前項主動參與或協助取締、舉發之人身分應予保密。第3項：獎勵之對象、基準、範圍及其他相關事項之辦法，由中央主管機關定之。",
 "How must the authority treat those who help intercept or report violations under this Act?",
 ["The authority may reward them and must keep their identity confidential; the rules on eligible persons, criteria and scope of rewards are set by the central competent authority","The authority must pay a fixed reward but owes no duty of confidentiality; the rules on eligible persons, criteria and scope are set separately by local authorities","The authority may reward them but must send their identity data to judicial authorities for record; eligibility, criteria and scope are approved case by case by the Executive Yuan","The authority rewards only law enforcement officers and not members of the public or groups; officers' reward criteria follow the Civil Service Performance Evaluation Act"],
 "Article 17."),

(OC,"第18條",1,"海保法-人才與教育",
 "主管機關就海洋保育人才培養及教育推廣負有何種義務？",
 ["應培養具備海洋保育及生物多樣性專業知識人才，並推廣海洋保育及生物多樣性教育課程，以提升民眾對於海洋生物多樣性之認識","應培養具備漁業經營及水產養殖專業知識人才，並推廣漁業技術及行銷通路教育課程，以提升民眾對於水產品消費安全之認識","應培養具備海域執法及蒐證移送專業知識人才，並推廣海岸巡防及治安維護教育課程，以提升民眾對於海域安全法制之認識","應培養具備海洋工程及船舶設計專業知識人才，並推廣航運管理及港埠作業教育課程，以提升民眾對於海運產業發展之認識"],"a",
 "第18條：主管機關應培養具備海洋保育及生物多樣性專業知識人才，並推廣海洋保育及生物多樣性教育課程，以提升民眾對於海洋生物多樣性之認識。第1條並以推動海洋保育教育為立法目的之一；第26條第2項另要求海洋保育講習課程應包含原住民族知識以及原住民族生物多樣性課程。",
 "What duty do the authorities have regarding conservation talent and education?",
 ["To cultivate personnel with professional knowledge of marine conservation and biodiversity and to promote education courses on them, so as to raise public awareness of marine biodiversity","To cultivate personnel with professional knowledge of fishery operation and aquaculture and to promote courses on fishing techniques and marketing, so as to raise public awareness of seafood safety","To cultivate personnel with professional knowledge of maritime enforcement and evidence-gathering and to promote courses on coastal patrol and public order, so as to raise public awareness of maritime law","To cultivate personnel with professional knowledge of marine engineering and ship design and to promote courses on shipping management and port operations, so as to raise public awareness of the shipping industry"],
 "Article 18; Articles 1 and 26."),

(OC,"第19條",2,"海保法-國際合作",
 "主管機關為促進海洋保育、生物多樣性保護及永續利用，得為何種國際性作為？",
 ["得自行或透過國際組織、學術研究機構進行國際合作，並對人民、民間團體、原住民各族參與國際交流活動，給予獎勵或補助","得自行或透過國際組織進行國際合作，但不得對人民、民間團體或原住民各族參與國際交流活動給予任何形式之獎勵或補助","應報請外交部核准後始得透過國際組織進行國際合作，並對參與國際交流之公務人員給予差旅費補助，民間團體不予補助","應委由中央目的事業主管機關統一辦理國際合作事宜，主管機關僅得對學術研究機構參與國際交流活動給予獎勵或補助"],"a",
 "第19條：主管機關為促進海洋保育、海洋生物多樣性保護及永續利用，得自行或透過國際組織、學術研究機構進行國際合作，並對人民、民間團體、原住民各族參與國際交流活動，給予獎勵或補助。第18條並要求主管機關培養海洋保育及生物多樣性專業人才並推廣相關教育課程。",
 "What international action may the authorities take to promote marine conservation, biodiversity and sustainable use?",
 ["They may pursue international cooperation on their own or through international organizations and academic institutions, and may reward or subsidize people, civil groups and indigenous peoples taking part in international exchanges","They may pursue international cooperation on their own or through international organizations, but may give no reward or subsidy of any kind to people, civil groups or indigenous peoples taking part in international exchanges","They must obtain foreign ministry approval before cooperating through international organizations, and may subsidize the travel of civil servants attending exchanges but not that of civil groups","They must leave international cooperation to the central industry authorities to handle centrally, and may reward or subsidize only academic institutions taking part in international exchanges"],
 "Article 19; Article 18."),

(OC,"第20條",3,"海保法-復育措施",
 "為執行海洋生物復育，主管機關或中央目的事業主管機關得辦理哪些復育措施？",
 ["得依海洋生物復育措施辦理原則，自行或委託其他機關（構）、法人、漁會或團體辦理人工復育設施之投放、海洋動物之培育或野放、海洋植物之栽植及其他復育之必要措施","得依海洋生物復育措施辦理原則，自行或委託其他機關（構）、法人、漁會或團體辦理海洋廢棄物之打撈、海域油污之清除、底泥之疏濬及其他海域環境整治之必要措施","得依海洋生物復育措施辦理原則，自行或委託其他機關（構）、法人、漁會或團體辦理漁船之收購減量、漁具之汰換補助、漁民之轉業輔導及其他漁業結構調整措施","得依海洋生物復育措施辦理原則，自行或委託其他機關（構）、法人、漁會或團體辦理海洋保護區之劃設、界標之設置、巡護勤務之執行及其他海域管制之必要措施"],"a",
 "第20條第1項：為執行海洋生物復育，主管機關或中央目的事業主管機關得依海洋生物復育措施辦理原則，自行或委託其他機關（構）、法人、漁會或團體辦理人工復育設施之投放、海洋動物之培育或野放、海洋植物之栽植及其他復育之必要措施。第3項：海洋生物復育措施辦理原則，由中央主管機關會同中央漁業主管機關定之。",
 "What restoration measures may the authorities carry out to restore marine organisms?",
 ["Following the principles for marine organism restoration measures, they may act themselves or commission agencies, juridical persons, fishermen's associations or groups to place artificial restoration installations, breed or release marine animals, plant marine flora and take other necessary restoration measures","Following the principles for marine organism restoration measures, they may act themselves or commission agencies, juridical persons, fishermen's associations or groups to salvage marine debris, clean up oil spills, dredge sediment and take other necessary sea area remediation measures","Following the principles for marine organism restoration measures, they may act themselves or commission agencies, juridical persons, fishermen's associations or groups to buy back and reduce fishing vessels, subsidize gear replacement, help fishers change jobs and make other fishery structural adjustments","Following the principles for marine organism restoration measures, they may act themselves or commission agencies, juridical persons, fishermen's associations or groups to designate protected areas, set boundary markers, conduct patrol duties and take other necessary sea control measures"],
 "Article 20, paragraphs 1 and 3."),

(OC,"第20條",2,"海保法-自行復育",
 "主管機關以外之機關（構）、自然人、法人或團體自行辦理復育措施前，應踐行何種程序？違者如何處罰？",
 ["應依海洋生物復育措施辦理原則提出復育計畫，報經主管機關同意後始得為之；未經同意自行辦理者，處新臺幣五萬元以上十五萬元以下罰鍰，但原住民基於傳統文化、祭儀、生活所需之保育行為不在此限","應依海洋生物復育措施辦理原則提出復育計畫，報請主管機關備查後即得為之；未報請備查自行辦理者，處新臺幣三萬元以上三十萬元以下罰鍰，並無任何除外或免罰之規定可資適用","應向中央漁業主管機關申請許可後始得辦理復育措施；未經許可自行辦理者，處新臺幣一萬元以上十五萬元以下罰鍰，並得令其限期回復原狀，屆期未回復者得按次連續處罰","得逕行辦理復育措施而無須提出任何計畫或報經同意；惟其復育措施致生海洋生態危害者，處新臺幣五萬元以上五十萬元以下罰鍰，並應令其接受海洋保育講習課程"],"a",
 "第20條第2項：第1項以外之機關（構）、自然人、法人或團體自行辦理復育措施前，應依海洋生物復育措施辦理原則，提出復育計畫，報經主管機關同意後，始得為之。第25條：違反第20條第2項規定，未經主管機關同意自行辦理復育措施者，處新臺幣五萬元以上十五萬元以下罰鍰；但原住民基於傳統文化、祭儀、生活所需之保育行為，不在此限。",
 "What must other entities do before carrying out restoration measures themselves, and how is breach penalized?",
 ["They must submit a restoration plan under the restoration principles and obtain the authority's consent first; acting without consent brings a fine of NT$50,000 to NT$150,000, except for indigenous conservation acts for traditional cultural, ritual or livelihood needs","They must submit a restoration plan under the restoration principles and file it with the authority for record first; acting without filing brings a fine of NT$30,000 to NT$300,000, with no exemption of any kind available","They must apply to the central fisheries authority for a permit before carrying out any restoration measures; acting without a permit brings a fine of NT$10,000 to NT$150,000, together with an order to restore within a time limit and consecutive penalties if not done","They may carry out restoration directly without any plan or consent; but where the measures harm marine ecology a fine of NT$50,000 to NT$500,000 applies together with an order to attend conservation classes"],
 "Article 20, paragraph 2; Article 25."),

# ---------- 第四章 罰則 ----------
(OC,"第21條",2,"海保法-核心區罰鍰",
 "違反第十條第一項進入海洋庇護區核心區者，其受罰對象及罰鍰額度為何？",
 ["處行為人、海陸域交通工具駕駛人或船長新臺幣五萬元以上五十萬元以下罰鍰","處交通工具所有人或船舶所有人新臺幣五萬元以上五十萬元以下罰鍰","處行為人、海陸域交通工具駕駛人或船長新臺幣一萬元以上五萬元以下罰鍰","處行為人所屬法人或團體新臺幣十萬元以上一百萬元以下之罰鍰及沒入"],"a",
 "第21條第1項：違反第10條第1項規定，進入海洋庇護區之核心區者，處行為人、海陸域交通工具駕駛人或船長新臺幣五萬元以上五十萬元以下罰鍰。第10條第1項並就國家安全或軍事目的、公務目的、船舶連續不停迅速通過及經中央主管機關同意之科學研究等情形設有但書。",
 "Who is fined and how much for entering a sanctuary core zone in breach of Article 10(1)?",
 ["The actor, the land or sea vehicle operator or the master is fined NT$50,000 to NT$500,000","The owner of the vehicle or the owner of the vessel is fined NT$50,000 to NT$500,000","The actor, the land or sea vehicle operator or the master is fined NT$10,000 to NT$50,000","The juridical person or group to which the actor belongs is fined NT$100,000 to NT$1 million"],
 "Article 21, paragraph 1; Article 10, paragraph 1."),

(OC,"第21條",2,"海保法-誤入不罰",
 "誤入海洋庇護區核心區者，其處罰規定為何？",
 ["經勸導駛離者不罰；但其為最近二年內經勸導又再違反者，不在此限","經勸導駛離者不罰；但其為最近五年內經勸導又再違反者，不在此限","經勸導駛離者仍應處罰，僅得減輕其罰鍰額度至法定最低額之半數","經勸導駛離者一律不罰，縱最近二年內經勸導又再違反者，仍不處罰"],"a",
 "第21條第2項：誤入海洋庇護區之核心區，經勸導駛離者，不罰；但其為最近二年內經勸導又再違反者，不在此限。第1項則就違反第10條第1項進入核心區者，處行為人、海陸域交通工具駕駛人或船長新臺幣五萬元以上五十萬元以下罰鍰。",
 "How is accidental entry into a sanctuary core zone treated?",
 ["No penalty where the person leaves after advice; unless they were advised and offended again within the past two years","No penalty where the person leaves after advice; unless they were advised and offended again within the past five years","A penalty still applies even after leaving on advice, though the fine may be halved from the statutory minimum","No penalty in any case, even where the person was advised and offended again within the past two years"],
 "Article 21, paragraph 2."),

(OC,"第22條",2,"海保法-緩衝區罰鍰",
 "於海洋庇護區緩衝區內未經許可從事第十一條第一項所定禁止行為者，應處多少罰鍰？",
 ["處新臺幣三萬元以上三十萬元以下罰鍰","處新臺幣五萬元以上五十萬元以下罰鍰","處新臺幣一萬元以上十五萬元以下罰鍰","處新臺幣二萬元以上十萬元以下之罰鍰"],"a",
 "第22條：違反第11條第1項規定，於海洋庇護區之緩衝區內，未經許可從事該項所定禁止行為者，處新臺幣三萬元以上三十萬元以下罰鍰；但原住民基於傳統文化、祭儀、生活所需之利用的行為，不在此限。第11條第1項所定禁止行為包括水產養殖、採捕海洋生物、開挖濬深航道或施作海洋工程、鋪設電纜管道設施或結構及從事探礦或採礦。",
 "What fine applies to unpermitted prohibited activity in a sanctuary buffer zone under Article 11(1)?",
 ["A fine of NT$30,000 to NT$300,000","A fine of NT$50,000 to NT$500,000","A fine of NT$10,000 to NT$150,000","A fine of NT$20,000 to NT$100,000"],
 "Article 22; Article 11, paragraph 1."),

(OC,"第23條",2,"海保法-一萬至十五萬",
 "下列哪些情形應處新臺幣一萬元以上十五萬元以下罰鍰？",
 ["於海洋庇護區之永續利用區內未經許可從事第十二條所定禁止行為；違反第十四條第一項公告事項","於海洋庇護區之緩衝區內未經許可從事第十一條所定禁止行為；違反第十條第一項進入核心區","無正當理由規避、妨礙或拒絕海洋生物資源調查；無正當理由規避、妨礙或拒絕海洋保育觀察員","未經主管機關同意自行辦理復育措施；拒不接受主管機關所令之海洋保育講習課程或時數不足"],"a",
 "第23條：有下列情形之一者，處新臺幣一萬元以上十五萬元以下罰鍰：一、違反第12條規定，於海洋庇護區之永續利用區內，未經許可從事該條所定禁止行為。二、違反第14條第1項公告事項。第22條就緩衝區違規處三萬元以上三十萬元以下，第24條就規避調查或觀察員處二萬元以上十萬元以下，第25條就未經同意自行復育處五萬元以上十五萬元以下。",
 "Which situations attract a fine of NT$10,000 to NT$150,000?",
 ["Carrying out prohibited activity without permit in a sanctuary's sustainable use zone under Article 12; and breaching matters announced under Article 14(1)","Carrying out prohibited activity without permit in a sanctuary's buffer zone under Article 11; and entering the core zone in breach of Article 10(1)","Evading, obstructing or refusing a marine biological resource survey without justification; and evading, obstructing or refusing a marine conservation observer","Carrying out restoration measures without the authority's consent; and refusing to attend the ordered marine conservation classes or completing insufficient hours"],
 "Article 23; Articles 22, 24 and 25."),

(OC,"第24條",2,"海保法-規避調查罰則",
 "無正當理由規避、妨礙或拒絕海洋生物資源調查或海洋保育觀察員執行任務者，應處多少罰鍰？",
 ["處新臺幣二萬元以上十萬元以下罰鍰","處新臺幣五萬元以上五十萬元以下罰鍰","處新臺幣三萬元以上三十萬元以下罰鍰","處新臺幣一萬元以上十五萬元以下之罰鍰"],"a",
 "第24條：有下列情形之一者，處新臺幣二萬元以上十萬元以下罰鍰：一、違反第15條第2項規定，無正當理由規避、妨礙或拒絕海洋生物資源調查或海洋庇護區保育計畫實施。二、違反第16條第2項規定，無正當理由規避、妨礙或拒絕海洋保育觀察員執行觀察、監測或蒐集資料。",
 "What fine applies for evading, obstructing or refusing a resource survey or an observer's duties without justification?",
 ["A fine of NT$20,000 to NT$100,000","A fine of NT$50,000 to NT$500,000","A fine of NT$30,000 to NT$300,000","A fine of NT$10,000 to NT$150,000"],
 "Article 24; Articles 15 and 16."),

(OC,"第25條",2,"海保法-未經同意復育",
 "未經主管機關同意自行辦理復育措施者，應如何處罰？有無除外規定？",
 ["處新臺幣五萬元以上十五萬元以下罰鍰；但原住民基於傳統文化、祭儀、生活所需之保育行為，不在此限","處新臺幣三萬元以上三十萬元以下罰鍰；但原住民基於傳統文化、祭儀、生活所需之保育行為，不在此限","處新臺幣一萬元以上十五萬元以下罰鍰；原住民基於傳統文化、祭儀或生活所需之保育行為，仍應處罰","處新臺幣二萬元以上十萬元以下罰鍰；但經地方主管機關事後追認之復育行為，得減半處以其應納之罰鍰"],"a",
 "第25條：違反第20條第2項規定，未經主管機關同意自行辦理復育措施者，處新臺幣五萬元以上十五萬元以下罰鍰；但原住民基於傳統文化、祭儀、生活所需之保育行為，不在此限。第20條第2項要求主管機關以外之機關（構）、自然人、法人或團體自行辦理復育措施前，應依海洋生物復育措施辦理原則提出復育計畫，報經主管機關同意後始得為之。",
 "How is carrying out restoration measures without the authority's consent penalized, and is there any exemption?",
 ["A fine of NT$50,000 to NT$150,000; but indigenous conservation acts for traditional cultural, ritual or livelihood needs are exempt","A fine of NT$30,000 to NT$300,000; but indigenous conservation acts for traditional cultural, ritual or livelihood needs are exempt","A fine of NT$10,000 to NT$150,000; indigenous conservation acts for traditional cultural, ritual or livelihood needs are still penalized","A fine of NT$20,000 to NT$100,000; but restoration later ratified by the local competent authority attracts only half the fine due"],
 "Article 25; Article 20, paragraph 2."),

(OC,"第26條",3,"海保法-保育講習",
 "違反核心區、緩衝區、永續利用區規定或第十四條第一項公告事項者，主管機關應命其接受何種課程？",
 ["應令其接受二小時以上十二小時以下之海洋保育講習課程；該課程應包含原住民族知識以及原住民族生物多樣性課程","應令其接受四小時以上二十四小時以下之海洋保育講習課程；該課程應包含海域執法法制及海洋污染防治相關課程","應令其接受一小時以上六小時以下之海洋保育講習課程；該課程應包含漁業法規及水產養殖技術等實務操作課程","應令其接受八小時以上四十八小時以下之海洋保育講習課程；該課程應包含船舶操作安全及航行避碰規則等課程"],"a",
 "第26條第1項：違反第10條第1項、第11條第1項、第12條規定或第14條第1項公告事項者，主管機關應令其接受二小時以上十二小時以下之海洋保育講習課程。第2項：該海洋保育講習課程，應包含原住民族知識以及原住民族生物多樣性課程。第4項並授權中央主管機關訂定課程內容、實施對象及方式之辦法。",
 "What course must the authority order for breaches of the zone rules or Article 14(1) announcements?",
 ["Attendance at a marine conservation class of not less than two and not more than twelve hours; the course must include indigenous knowledge and indigenous biodiversity content","Attendance at a marine conservation class of not less than four and not more than twenty-four hours; the course must include maritime enforcement law and marine pollution control content","Attendance at a marine conservation class of not less than one and not more than six hours; the course must include fishery regulations and practical aquaculture technique content","Attendance at a marine conservation class of not less than eight and not more than forty-eight hours; the course must include ship handling safety and collision avoidance rules content"],
 "Article 26, paragraphs 1, 2 and 4."),

(OC,"第26條",2,"海保法-拒不接受講習",
 "拒不接受海洋保育講習課程或時數不足者，應如何處罰？",
 ["處新臺幣三千元以上一萬元以下罰鍰；經通知令其限期接受講習或補足時數仍不接受或未補足者，得按次處罰至其接受講習或補足時數為止","處新臺幣一萬元以上五萬元以下罰鍰；經通知令其限期接受講習或補足時數仍不接受或未補足者，應移送司法機關依法追訴其刑事責任","處新臺幣三千元以上一萬元以下罰鍰；經通知令其限期接受講習仍不接受者，僅得再處罰一次，不得按次連續處罰至其接受為止","處新臺幣六千元以上三萬元以下罰鍰；經通知令其限期接受講習或補足時數仍不接受者，得逕行加倍處罰並公布其姓名及違規事實"],"a",
 "第26條第3項：拒不接受第1項海洋保育講習課程或時數不足者，處新臺幣三千元以上一萬元以下罰鍰，經通知令其限期接受講習或補足時數仍不接受或未補足時數者，得按次處罰至其接受講習或補足時數為止。第1項並定明違反第10條第1項、第11條第1項、第12條或第14條第1項公告事項者，應令其接受二小時以上十二小時以下之講習課程。",
 "How is refusal to attend the marine conservation class or completing insufficient hours penalized?",
 ["A fine of NT$3,000 to NT$10,000; where after notice to attend or make up hours within a time limit the person still fails to do so, repeat penalties apply until attendance or the hours are completed","A fine of NT$10,000 to NT$50,000; where after notice to attend or make up hours within a time limit the person still fails to do so, the case must be referred to judicial authorities for prosecution","A fine of NT$3,000 to NT$10,000; where after notice to attend within a time limit the person still fails to do so, only one further penalty may be imposed and no consecutive repeat penalties apply","A fine of NT$6,000 to NT$30,000; where after notice to attend or make up hours the person still fails to do so, the penalty is doubled and the name and violation are made public"],
 "Article 26, paragraphs 1 and 3."),

(OC,"第27條",2,"海保法-回復原狀",
 "經依第二十一條至第二十三條規定處罰者，就其造成之損害應負何種責任？調查費用由誰負擔？",
 ["其損害部分應回復原狀；不能回復原狀或回復顯有重大困難者，應賠償其損害；為調查回復原狀所支出之必要費用，由賠償義務人負擔","其損害部分應回復原狀；不能回復原狀者即免除其一切責任，無須賠償損害；為調查回復原狀所支出之必要費用，由主管機關編列年度預算支應","其損害部分得由主管機關代為回復原狀；行為人僅須負擔材料成本而不負賠償責任；為調查回復原狀所支出之必要費用，由海洋保育基金全額支應","其損害部分應賠償而無回復原狀義務；賠償金額由主管機關逕行核定且不得爭訟；為調查回復原狀所支出之必要費用，由檢舉人與賠償義務人分擔"],"a",
 "第27條第1項：違反本法規定，經依第21條至第23條規定處罰者，其損害部分應回復原狀；不能回復原狀或回復顯有重大困難者，應賠償其損害。第2項：為調查回復原狀所支出之必要費用，由賠償義務人負擔。第21條至第23條分別規範進入核心區、緩衝區未經許可從事禁止行為、永續利用區未經許可從事禁止行為及違反第14條第1項公告事項等情形。",
 "What liability for damage follows a penalty under Articles 21 to 23, and who bears the investigation costs?",
 ["The damage must be restored to its original state; where restoration is impossible or would be seriously difficult, damages must be paid; the necessary costs of investigating restoration are borne by the person liable in damages","The damage must be restored to its original state; where restoration is impossible all liability is discharged and no damages are payable; the necessary costs of investigating restoration come from the authority's annual budget","The authority may carry out restoration on the offender's behalf; the offender pays only material costs and owes no damages; the necessary costs of investigating restoration are met in full by the marine conservation fund","Damages are payable with no duty to restore; the amount is fixed by the authority and may not be disputed; the necessary costs of investigating restoration are shared between the informant and the person liable"],
 "Article 27; Articles 21-23."),

# ---------- 第五章 附則 ----------
(OC,"第28條",3,"海保法-公民訴訟",
 "主管機關疏於執行本法時，受害人民或公益團體得如何救濟？向何法院起訴？",
 ["得敘明疏於執行之具體內容以書面告知主管機關；主管機關於書面告知送達之日起六十日內仍未依法執行者，得以該主管機關為被告，對其怠於執行職務之行為，直接向高等行政法院提起訴訟，請求判令其執行","得敘明疏於執行之具體內容以書面告知主管機關；主管機關於書面告知送達之日起三十日內仍未依法執行者，得以該主管機關為被告，對其怠於執行職務之行為，直接向地方法院提起訴訟，請求判令其執行","得逕行以該主管機關為被告向高等行政法院提起訴訟請求判令執行，無須先以書面告知；主管機關於收受起訴狀繕本之日起六十日內仍未執行者，法院應依職權逕為判決命其限期執行","得向監察院陳情並請求調查主管機關之失職情形；監察院於受理陳情之日起六十日內未為處理者，受害人民或公益團體始得向高等行政法院提起訴訟，請求判令主管機關執行"],"a",
 "第28條第1項：行為人違反本法或依本法授權訂定之法規命令而主管機關疏於執行時，受害人民或公益團體得敘明疏於執行之具體內容，以書面告知主管機關；主管機關於書面告知送達之日起六十日內仍未依法執行者，受害人民或公益團體得以該主管機關為被告，對其怠於執行職務之行為，直接向高等行政法院提起訴訟，請求判令其執行。第2項並定明高等行政法院得依職權判命被告機關支付適當律師費用、鑑定費用或其他訴訟費用予對維護海洋保育有具體貢獻之原告。第3項：書面告知格式由中央主管機關會商有關機關公告之。",
 "How may harmed persons or public interest groups seek redress when the authority neglects enforcement, and in which court?",
 ["They may notify the authority in writing stating the specifics of the neglect; if it still fails to act within sixty days of service, they may sue that authority directly in the High Administrative Court over its neglect of duty, seeking an order to enforce","They may notify the authority in writing stating the specifics of the neglect; if it still fails to act within thirty days of service, they may sue that authority directly in the district court over its neglect of duty, seeking an order to enforce","They may sue the authority directly in the High Administrative Court seeking an order to enforce without any prior written notice; if it still fails to act within sixty days of service of the complaint, the court must order enforcement ex officio","They may petition the Control Yuan to investigate the authority's dereliction; only if the Control Yuan fails to act within sixty days of the petition may they sue in the High Administrative Court seeking an order to enforce"],
 "Article 28, paragraphs 1-3."),

(OC,"第29條",3,"海保法-既有權利",
 "中央主管機關劃定海洋庇護區前已合法取得同意或許可之行為，其效力為何？",
 ["已於該海域合法取得目的事業主管機關同意鋪設電纜、管道、設施、結構、從事探礦或採礦或其他經許可核准之行為者，不受第十條至第十二條規定之限制，得繼續從事許可或核准行為至有效期限屆滿為止","已於該海域合法取得目的事業主管機關同意鋪設電纜、管道、設施、結構或從事探礦採礦者，仍應自庇護區公告之日起六個月內停止其行為並拆除全部設施，其所受損失由中央主管機關予以補償","已於該海域合法取得目的事業主管機關同意之行為者，得繼續從事至有效期限屆滿為止，但應重新向中央主管機關申請許可並繳納規費，未申請者視為自始未取得任何同意或許可","已於該海域合法取得目的事業主管機關同意之行為者，一律不受第十條至第十二條規定之限制，且其許可效期屆滿後仍得逕行申請展延並繼續從事該等行為而無須另行取得許可"],"a",
 "第29條：中央主管機關依第8條規定劃定海洋庇護區前，已於該海域合法取得目的事業主管機關同意鋪設電纜、管道、設施、結構、從事探礦或採礦或其他經許可或核准之行為者，不受第10條至第12條規定之限制，得繼續從事許可或核准行為至有效期限屆滿為止。第8條第4項並就核心區劃定致既有使用人遭受特別犧牲之損失者，定有應予補償之規定。",
 "What is the effect of consents or permits lawfully obtained before a marine sanctuary is designated?",
 ["Those who lawfully obtained industry authority consent in those waters to lay cables, pipelines, facilities or structures, to prospect or mine, or for other permitted acts are not bound by Articles 10 to 12 and may continue the permitted acts until the permit expires","Those who lawfully obtained industry authority consent in those waters to lay cables, pipelines, facilities or structures or to prospect or mine must still stop and remove everything within six months of the sanctuary announcement, with losses compensated by the central authority","Those who lawfully obtained industry authority consent in those waters may continue until expiry, but must reapply to the central authority for a permit and pay fees, and failing to apply means the consent is treated as never having been obtained","Those who lawfully obtained industry authority consent in those waters are entirely free of Articles 10 to 12, and after the permit expires may simply apply for extension and continue those acts without obtaining any further permit"],
 "Article 29; Article 8, paragraph 4."),

(OC,"第30條",1,"海保法-施行細則",
 "本法施行細則之訂定機關為何？",
 ["由中央主管機關定之","由行政院會商中央主管機關定之","由中央主管機關報請立法院審議","由各直轄市、縣（市）主管機關定之"],"a",
 "第30條：本法施行細則，由中央主管機關定之。依第2條第1項，本法之中央主管機關為海洋委員會。本法另授權中央主管機關訂定之辦法尚包括第6條第2項認定標準、第8條第5項劃定基準與補償辦法、第13條許可辦法、第16條第4項觀察員管理辦法及第26條第4項講習辦法等。",
 "Which authority prescribes the enforcement rules of this Act?",
 ["The central competent authority","The Executive Yuan with the central authority","The central authority, subject to legislative review","Each municipal and county competent authority"],
 "Article 30; Articles 2, 6, 8, 13, 16 and 26."),

(OC,"第31條",2,"海保法-施行日期",
 "本法之施行日期如何規定？",
 ["由行政院定之","自公布日施行","自公布後六個月施行","自公布後一年施行"],"a",
 "第31條：本法施行日期，由行政院定之。相較之下，海岸管理法第46條係規定自公布日施行；海洋污染防治法第69條則除第11條及第17條之施行日期由行政院定之外，自公布日施行，三者之施行日期規定方式並不相同。",
 "How is the effective date of this Act provided?",
 ["It is set by the Executive Yuan","It takes effect on promulgation","It takes effect six months after promulgation","It takes effect one year after promulgation"],
 "Article 31."),
]
